import{Vector3,Group}from'three';import{EQUIPMENT,pocketOwners,pocketInfo}from'./equipment-data.js';
import{installInitialPlates}from'./plate-inventory.js';import{IFAK,INITIAL_IFAK_CONTENTS,MEDICAL_SUPPLIES}from'./medical-supplies.js';
import{storageCell}from'./equipment-inventory.js';
export const SEARCH_SECONDS={game:1,realistic:3,reality:5};
export function canSearch(body){const m=body?.medical?.actor?.medical;return!!m&&(body.medical.actor.isDead||m.isDead||m.isUnconscious);}
export function createEnemyItems(inv,enemy,forced='random'){
 const id=enemy.actor.id,add=item=>{item.originActor=id;inv.items.set(item.instanceId,item);return item;},slots={};
 for(const slot of['helmet','rig','belt']){const instanceId=id+':'+slot;slots[slot]=instanceId;add({instanceId,kind:'gear',definitionId:slot,owner:'actor:'+id+':'+slot});}
 const roll=(enemy.random()+enemy.random())%1,plateId=forced==='br4'?'plate_granit_br4':forced==='br5'?'plate_granit_br5':roll<.5?'plate_granit_br4':'plate_granit_br5';installInitialPlates(inv,inv.items.get(slots.rig),plateId,id);
 for(const slot of Object.values(inv.items.get(slots.rig).plateSlots))inv.items.get(slot).originActor=id;
 const gun=add({instanceId:id+':gun',kind:'weapon',definitionId:'ak74m',owner:'actor:'+id+':weapon',magazineId:id+':mag-0',chamber:'545_ps_gs',boltLocked:false,fireMode:'full'});add({instanceId:gun.magazineId,kind:'magazine',definitionId:'ak_545_30',owner:'weapon:'+gun.instanceId,rounds:Array(29).fill('545_ps_gs')});
 for(let n=1;n<=4;n++)add({instanceId:id+':mag-'+n,kind:'magazine',definitionId:'ak_545_30',owner:pocketOwners(n===4?'belt':'rig',slots[n===4?'belt':'rig'])[n===4?1:n+2],cell:{x:0,y:0},rounds:Array(30).fill('545_ps_gs')});
 const kit=add({instanceId:id+':ifak',kind:'medicalContainer',definitionId:IFAK.id,owner:pocketOwners('rig',slots.rig)[7],cell:{x:0,y:0}});
 for(const[n,[definitionId,x,y]]of INITIAL_IFAK_CONTENTS.entries()){const d=MEDICAL_SUPPLIES[definitionId];add({instanceId:id+':medical-'+n,kind:'medicalSupply',definitionId,owner:'container:'+kit.instanceId,cell:{x,y},remaining:d.units});}
 enemy.actor.loadWeightKg=Object.values(slots).reduce((n,id)=>n+inv.itemWeightKg(inv.items.get(id)),0)+inv.itemWeightKg(gun);enemy.equipmentSlots=slots;enemy.weaponItemId=gun.instanceId;enemy.plateChoice={plateId,roll,forced,tuning:'two existing LCG samples summed modulo1, 50:50 threshold; forced choice consumes same two samples'};inv.changed();return slots;
}
export function enemyFireInventory(inv,e){const gun=inv.items.get(e.weaponItemId),mag=inv.items.get(gun?.magazineId);gun.chamber=null;if(mag?.rounds.length)gun.chamber=mag.rounds.pop();gun.boltLocked=!gun.chamber;e.rounds=(mag?.rounds.length||0)+(gun.chamber?1:0);inv.revision++;}
export function enemyReloadInventory(inv,e){const gun=inv.items.get(e.weaponItemId);if(!gun)return false;const next=[...inv.items.values()].filter(i=>i.kind==='magazine'&&i.definitionId==='ak_545_30'&&i.rounds.length&&Object.values(e.equipmentSlots).includes(pocketInfo(i.owner)?.gearId)).sort((a,b)=>a.owner.localeCompare(b.owner)).sort((a,b)=>a.owner.startsWith('rig:')===b.owner.startsWith('rig:')?0:a.owner.startsWith('rig:')?-1:1)[0];if(!next){e.rounds=0;return false;}const previous=inv.items.get(gun.magazineId),owner=next.owner,cell=next.cell;previous.owner=owner;previous.cell={...cell};next.owner='weapon:'+gun.instanceId;delete next.cell;gun.magazineId=next.instanceId;if(!gun.chamber&&next.rounds.length)gun.chamber=next.rounds.pop();gun.boltLocked=!gun.chamber;e.rounds=next.rounds.length+(gun.chamber?1:0);inv.changed();return true;}
export function corpseAccess(inv,owner){const m=/^actor:(.+):(helmet|rig|belt|weapon)$/.exec(owner);if(!m)return null;return!!inv.corpseController?.accessible(m[1]);}
export class CorpseInventory{
 constructor({combat,inventory,world,bag,aim,physics,settings,onOpen}){Object.assign(this,{combat,inventory,world,bag,aim,physics,settings,onOpen});inventory.corpseController=this;this.searched=new Set();this.targetId=null;this.confirmCleanupUntil=0;bag.corpse=this;
  combat.onEnemyDeployed=e=>{createEnemyItems(inventory,e,settings.enemyPlateType||'random');world.syncWorn(true);};combat.onEnemyFired=e=>enemyFireInventory(inventory,e);combat.onEnemyReloaded=e=>enemyReloadInventory(inventory,e);combat.onEnemyDropped=e=>this.dropGun(e);combat.onEnemyCleanup=e=>this.cleanup(e);this.setupUI();
 }
 body(id=this.targetId){return this.combat.listEnemies().find(e=>e.actor.id===id)||null;}
 center(body){return body.registered.body.find(r=>r.shape.id==='chest').pose.position.clone();}
 accessible(id){const body=this.body(id);return!!body&&this.searched.has(id)&&canSearch(body)&&this.center(body).distanceTo(this.physics.feet)<=1.7;}
 nearby(){for(const e of this.combat.listEnemies()){const found=this.nearbyBody(e);if(found)return found;}return null;}
 nearbyBody(e){if(!canSearch(e))return null;const point=this.center(e),delta=point.clone().sub(this.aim.eye),along=delta.dot(this.aim.shotPose().direction);if(point.distanceTo(this.physics.feet)>1.5||along<=0||delta.clone().addScaledVector(this.aim.shotPose().direction,-along).length()>.34)return null;const hit=this.physics.ray(this.aim.eye,delta.clone().normalize(),delta.length());if(hit&&hit.distance<delta.length()-.35&&!String(hit.id).startsWith(e.actor.id))return null;return{kind:'corpse-search',targetId:e.actor.id,label:e.actor.id,action:'수색'};}
 search(id){const inv=this.inventory,e=this.body(id);if(!e||!canSearch(e)||this.center(e).distanceTo(this.physics.feet)>1.5)return inv.fail('죽었거나 의식 없는 가까운 대상만 수색할 수 있습니다.');if(inv.action||inv.canEquipmentAct?.()===false)return inv.fail();if(this.searched.has(id)){this.open(id);return true;}inv.action={kind:'gear-search',phase:'대상 수색',actorId:id,elapsed:0,duration:SEARCH_SECONDS[inv.treatmentMode]};inv.onEquipmentAction?.();return inv.changed();}
 open(id){this.targetId=id;this.bag.targetOpen=true;this.bag.storage.nearbyOpen=false;this.onOpen?.();this.bag.refresh();}
 strip(id){const inv=this.inventory,item=inv.items.get(id),root=item&&inv.rootOwner(item),e=this.combat.listEnemies().find(e=>root?.startsWith('actor:'+e.actor.id+':'));if(inv.action||!e||!canSearch(e)||!root?.startsWith('actor:'+e.actor.id+':')||!this.accessible(e.actor.id)||!['helmet','rig'].includes(item.definitionId))return inv.fail('수색 중인 대상의 헬멧·리그를 선택하세요.');inv.action={kind:'gear-strip',phase:'대상 장비 벗기',actorId:e.actor.id,itemId:id,elapsed:0,duration:EQUIPMENT.gearSeconds[inv.treatmentMode]};inv.onEquipmentAction?.();return inv.changed();}
 step(dt){const inv=this.inventory,a=inv.action;if(!['gear-search','gear-strip'].includes(a?.kind))return undefined;const e=this.body(a.actorId);if(!e||!canSearch(e)||this.center(e).distanceTo(this.physics.feet)>1.7){inv.cancel();return null;}a.elapsed=Math.min(a.duration,a.elapsed+dt);if(a.elapsed<a.duration-1e-8)return null;inv.action=null;if(a.kind==='gear-search'){this.searched.add(a.actorId);this.open(a.actorId);}else{const item=inv.items.get(a.itemId);if(!item||inv.onWorldDrop?.(item)===false)return inv.fail('장비를 바닥에 놓을 수 없습니다.');e.equipmentSlots[item.definitionId]=null;item.owner='ground:'+item.instanceId;delete item.cell;inv.onEquipmentChanged?.();}inv.changed();return a.kind;}
 take(id){const inv=this.inventory,item=inv.items.get(id);if(!item||!inv.canAccess(item.owner))return inv.fail('대상에 접근할 수 없습니다.');if(item.kind==='gear')return this.strip(id);const dest=storageCell(inv,item);if(!dest)return inv.fail('내 장비·배낭에 빈칸이 없습니다.');if(dest.owner==='bag'&&!inv.backpackOpen)return inv.openBackpack({kind:'move',id,x:dest.cell.x,y:dest.cell.y});return inv.move(id,dest.owner,dest.cell.x,dest.cell.y);}
 dropGun(e){const inv=this.inventory,item=inv.items.get(e.weaponItemId);if(!item||!e.droppedBody)return;e.gun.updateMatrixWorld(true);const root=new Group(),relative=e.gun.matrixWorld.clone().invert();this.world.freezeEnemyWeapon(e.gun,root,relative);const body=e.droppedBody,collider=body.collider(0);collider.setMass(inv.itemWeightKg(item));body.recomputeMassPropertiesFromColliders();e.gun.visible=false;root.position.copy(e.gun.position);root.quaternion.copy(e.gun.quaternion);this.world.scene.add(root);item.owner='ground:'+item.instanceId;const row={id:item.instanceId,root,body,collider,mass:inv.itemWeightKg(item),size:[.1,.28,.95],fallbackBox:false,onRemove:()=>{e.droppedBody=null;e.preparedDropBody=null;e.gun.visible=false;}};this.physics.surface.set(collider.handle,{id:'loot:'+item.instanceId,kind:'world-loot'});this.world.rows.set(item.instanceId,row);inv.changed();}
 requestCleanup(){const time=performance.now();if(this.confirmCleanupUntil<time){this.confirmCleanupUntil=time+5000;this.combat.cleanupPrompt=true;return{confirmed:false,message:'정리하면 시체에 남은 장비·물품이 사라집니다. 5초 안에 F를 다시 누르세요.'};}this.confirmCleanupUntil=0;this.combat.cleanupPrompt=false;return{confirmed:true};}
 cleanup(e){const inv=this.inventory,remove=[];for(const item of inv.items.values()){let root;try{root=inv.rootOwner(item);}catch{continue;}if(root.startsWith('actor:'+e.actor.id+':')||item.originActor===e.actor.id&&!item.claimed&&root.startsWith('ground:'))remove.push(item.instanceId);}for(const id of remove)this.world.remove(id);for(const id of remove)inv.items.delete(id);this.world.armorEquipment?.states.delete(e.actor.id);this.searched.delete(e.actor.id);if(this.targetId===e.actor.id){this.targetId=null;this.bag.targetOpen=false;}inv.changed();}
 setupUI(){const bag=this.bag,storage=bag.storage,source=storage.sources;this.panel=document.createElement('section');this.panel.id='corpseItems';source.append(this.panel);this.tab=document.createElement('button');this.tab.id='corpseTab';this.tab.type='button';this.tab.textContent='대상 · 수색';this.tab.addEventListener('click',()=>{if(this.targetId&&this.accessible(this.targetId)){bag.targetOpen=true;bag.refresh();}});source.querySelector('.medical-sources').append(this.tab);document.getElementById('nearbyTab').addEventListener('click',()=>{bag.targetOpen=false;bag.refresh();});const buttons=document.querySelector('#medicalItems>.medical-sources').querySelectorAll('button');this.patientButton=buttons[1];this.patientButton.id='medicalCorpse';this.patientButton.addEventListener('click',()=>{bag.targetOpen=true;storage.medicalTarget=true;storage.medicalNearby=false;bag.refresh();});storage.selfButton.addEventListener('click',()=>{storage.medicalTarget=false;bag.targetOpen=false;});storage.nearButton.addEventListener('click',()=>{storage.medicalTarget=false;bag.targetOpen=false;});}
 update(){const inv=this.inventory,bag=this.bag,e=this.body(),available=e&&this.accessible(e.actor.id);this.tab.disabled=this.patientButton.disabled=!available;this.patientButton.setAttribute('aria-pressed',String(!!bag.storage.medicalTarget));if(!available)bag.targetOpen=false;this.panel.hidden=!bag.targetOpen;bag.storage.world.hidden=!!bag.targetOpen||!bag.storage.nearbyOpen;if(!bag.targetOpen||bag.gesture)return;const stamp=[inv.revision,bag.selectedId,this.targetId,bag.targetOpen].join(':');if(stamp===this.stamp)return;this.stamp=stamp;this.panel.replaceChildren();const title=document.createElement('h3');title.textContent=e.actor.id+' · 대상 장비';this.panel.append(title);
  for(const slot of['helmet','rig','belt']){const item=inv.items.get(e.equipmentSlots[slot]);if(!item)continue;const row=document.createElement('article');row.className='m7-corpse-gear';row.append(bag.makeItem(item));if(slot!=='belt'){const strip=document.createElement('button');strip.type='button';strip.textContent='벗기';strip.dataset.stripItem=item.instanceId;strip.addEventListener('click',()=>bag.run(()=>this.strip(item.instanceId)));row.append(strip);}if(slot==='rig'){const open=document.createElement('button');open.type='button';open.textContent='플레이트';open.addEventListener('click',()=>{bag.plates.open(item.instanceId);bag.refresh();});row.append(open);}this.panel.append(row);if(slot!=='helmet')bag.storage.pockets(slot,this.panel,item.instanceId);}
 }
 snapshot(){return{targetId:this.targetId,searched:[...this.searched],open:!!this.bag.targetOpen,available:this.targetId?this.accessible(this.targetId):false};}
 reset(){this.searched.clear();this.targetId=null;this.bag.targetOpen=false;this.confirmCleanupUntil=0;}
}

